import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;

public class Main {

    static int N, Q;
    static int[] p;
    static int[] depth;
    static int[][] up;
    static int LOGN = 19;

    // DSU para nós absorvidos e folhas
    static int[] dsu;

    // Controle de líderes ativos
    static boolean[] isActiveLeader;
    static ArrayList<Integer>[] activeChildren;

    static int find(int i) {
        if (dsu[i] == i) return i;
        return dsu[i] = find(dsu[i]);
    }

    static int getKthAncestor(int node, int k) {
        for (int j = LOGN - 1; j >= 0; j--) {
            if ((k & (1 << j)) != 0) {
                node = up[j][node];
            }
        }
        return node;
    }

    static void absorbSubtree(int u, int root) {
        for (int child : activeChildren[u]) {
            dsu[child] = root;
            isActiveLeader[child] = false;
            absorbSubtree(child, root);
        }
        activeChildren[u].clear();
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        N = fs.nextInt();
        p = new int[N + 1];
        depth = new int[N + 1];
        up = new int[LOGN][N + 1];
        dsu = new int[N + 1];
        isActiveLeader = new boolean[N + 1];
        activeChildren = new ArrayList[N + 1];

        for (int i = 1; i <= N; i++) {
            activeChildren[i] = new ArrayList<>();
        }

        boolean[] hasChildren = new boolean[N + 1];
        for (int i = 2; i <= N; i++) {
            p[i] = fs.nextInt();
            hasChildren[p[i]] = true;
        }

        // Construção do Binary Lifting e profundidades
        depth[1] = 0;
        up[0][1] = 1;
        for (int i = 2; i <= N; i++) {
            depth[i] = depth[p[i]] + 1;
            up[0][i] = p[i];
        }

        for (int j = 1; j < LOGN; j++) {
            for (int i = 1; i <= N; i++) {
                up[j][i] = up[j - 1][up[j - 1][i]];
            }
        }

        // Inicialização dos líderes ativos e DSU
        for (int i = 1; i <= N; i++) {
            if (hasChildren[i]) {
                isActiveLeader[i] = true;
                dsu[i] = i;
            } else {
                isActiveLeader[i] = false;
                dsu[i] = p[i]; // Folha inicial aponta para seu pai original
            }
        }

        // Conectar a árvore de líderes ativos
        for (int i = 2; i <= N; i++) {
            if (isActiveLeader[i]) {
                activeChildren[p[i]].add(i);
            }
        }

        Q = fs.nextInt();
        for (int q = 0; q < Q; q++) {
            int type = fs.nextInt();
            if (type == 1) {
                int v = fs.nextInt();
                int k = fs.nextInt();

                if (isActiveLeader[v]) {
                    // v ainda é líder ativo: seu caminho para a raiz é o caminho original
                    int ans = getKthAncestor(v, k);
                    out.println(ans);
                } else {
                    // v foi absorvido ou era folha: seu superior direto é find(v)
                    int parent = find(v);
                    if (k == 1) {
                        out.println(parent);
                    } else {
                        int ans = getKthAncestor(parent, k - 1);
                        out.println(ans);
                    }
                }
            } else {
                int v = fs.nextInt();
                // Se v for líder ativo, ele absorve todos os líderes ativos em sua subárvore
                if (isActiveLeader[v]) {
                    absorbSubtree(v, v);
                }
            }
        }

        out.flush();
    }

    // Leitor rápido de entrada para lidar com até 10^5 inteiros eficientemente
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new RuntimeException("Caractere inválido");
                }
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res;
        }
    }
}
